export default function ({ url }) {
  const u = new URL(url);
  if (u.protocol !== "https:") throw Error("Enter an HTTPS company website");
  return {
    body: {
      query: "Companies that compete with " + u.hostname,
      numResults: 10,
      type: "auto",
      excludeDomains: [u.hostname, "github.com", "linkedin.com"],
    },
  };
}

