export default function ({ body, previous }) {
  if (!Array.isArray(body?.results)) throw Error("Invalid Exa results");
  const seen = new Set(),
    rows = [];
  for (const x of body.results) {
    try {
      const u = new URL(x.url);
      if (u.protocol === "https:" && !seen.has(u.hostname)) {
        seen.add(u.hostname);
        rows.push({ url: u.origin, title: x.title || u.hostname });
      }
    } catch {}
  }
  const i = (previous?.i ?? -1) + 1;
  return {
    state: { i },
    more: i < rows.length,
    url: rows[i]?.url ?? "",
    title: rows[i]?.title ?? "",
  };
}

