export default async function ({ url, overview, product, reviews }, ctx) {
  const key = "competitor-report:" + url,
    state = await ctx.state.get(key);
  if (state?.status === "pending") throw Error("Inspect Notion before retry");
  const text = JSON.stringify(
      {
        overview: JSON.parse(overview),
        product: JSON.parse(product),
        reviews: JSON.parse(reviews),
      },
      null,
      2,
    ),
    parts = [];
  for (let i = 0; i < text.length; i += 1800)
    parts.push({
      object: "block",
      type: "paragraph",
      paragraph: { rich_text: [{ type: "text", text: { content: text.slice(i, i + 1800) } }] },
    });
  if (!state) await ctx.state.set(key, { status: "pending" });
  return { key, skip: state?.status === "done", children: parts };
}

