export default function ({ body }) {
  if (body?.error) throw Error("Search failed");
  return {
    result: JSON.stringify(
      (body?.organic_results ?? [])
        .slice(0, 10)
        .map((x) => ({ title: x.title, link: x.link, snippet: x.snippet })),
    ),
  };
}

